trait Shape {
    fn sides(&self) -> u32;
    fn describe(&self) -> String {
        format!("{} sides", self.sides())
    }
}

struct Triangle;
struct Circle;

impl Shape for Triangle {
    fn sides(&self) -> u32 {
        3
    }
}

impl Shape for Circle {
    fn sides(&self) -> u32 {
        0
    }
    fn describe(&self) -> String {
        String::from("round")
    }
}

fn main() {
    println!("{}, {}", Triangle.describe(), Circle.describe());
}

trait Score {
    fn base(&self) -> i32;
    fn total(&self) -> i32 {
        self.base() * 2
    }
}

struct A;
struct B;

impl Score for A {
    fn base(&self) -> i32 {
        5
    }
}

impl Score for B {
    fn base(&self) -> i32 {
        7
    }
    fn total(&self) -> i32 {
        self.base() + 1
    }
}

fn sum<T: Score, U: Score>(a: &T, b: &U) -> i32 {
    a.total() + b.total()
}

fn main() {
    println!("{}", sum(&A, &B));
}
